#include <stdlib.h>
#include <limits.h>

typedef struct {
    int x;
    int y;
} Point;

int comparePoints(const void *a, const void *b) {
    Point *pa = (Point *)a;
    Point *pb = (Point *)b;
    if (pa->x != pb->x) return pa->x - pb->x;
    return pa->y - pb->y;
}

int min(int a, int b) {
    return a < b ? a : b;
}

int minAreaRect(int** points, int pointsSize, int* pointsColSize){
    // Sort points by x, then y
    Point *pts = (Point *)malloc(pointsSize * sizeof(Point));
    for (int i = 0; i < pointsSize; i++) {
        pts[i].x = points[i][0];
        pts[i].y = points[i][1];
    }
    qsort(pts, pointsSize, sizeof(Point), comparePoints);

    // We want to find pairs of points with the same x coordinate and record their y pairs.
    // For each x, we store the y coordinates in an array.
    // Then for each pair of y's, we check if we have seen this y pair before at a different x.
    // If yes, we can form a rectangle and calculate area.

    // To do this efficiently, we can:
    // - Group points by x coordinate.
    // - For each x, get the sorted list of y's.
    // - For each pair of y's in that x, check if this pair was seen before at some previous x.
    // - Keep a map from y-pair to last x coordinate where it was seen.
    // - When we find a repeated y-pair, calculate area = (x - last_x) * (y2 - y1).

    // Since coordinates can be large, we cannot use a direct array for mapping y-pairs.
    // We'll use a hash map keyed by y-pair (y1,y2).
    // Because y can be up to 40000, we can encode y1,y2 as a single 64-bit key: (long long)y1 * 40001 + y2

    // First group points by x:
    // We'll store unique x's and for each x, the list of y's.
    // Since points are sorted by x then y, we can do this in one pass.

    int maxPoints = pointsSize;
    int *xs = (int *)malloc(maxPoints * sizeof(int));
    int **ysByX = (int **)malloc(maxPoints * sizeof(int *));
    int *ysCount = (int *)malloc(maxPoints * sizeof(int));
    int xsCount = 0;

    int currentX = -1;
    int yListCapacity = 10;

    for (int i = 0; i < maxPoints; i++) {
        if (pts[i].x != currentX) {
            currentX = pts[i].x;
            xs[xsCount] = currentX;
            ysByX[xsCount] = (int *)malloc(yListCapacity * sizeof(int));
            ysCount[xsCount] = 0;
            xsCount++;
        }
        int idx = xsCount - 1;
        if (ysCount[idx] == yListCapacity) {
            yListCapacity *= 2;
            ysByX[idx] = (int *)realloc(ysByX[idx], yListCapacity * sizeof(int));
        }
        ysByX[idx][ysCount[idx]++] = pts[i].y;
    }

    // Hash map from y-pair to last x coordinate
    // We'll implement a simple open addressing hash map for (long long) key -> int value

    #define HASH_SIZE 131071 // a large prime near 2^17

    typedef struct {
        long long key;
        int val;
    } HashEntry;

    HashEntry *hashMap = (HashEntry *)malloc(HASH_SIZE * sizeof(HashEntry));
    for (int i = 0; i < HASH_SIZE; i++) {
        hashMap[i].key = -1;
        hashMap[i].val = -1;
    }

    long long encodePair(int y1, int y2) {
        return (long long)y1 * 40001LL + y2;
    }

    int hash(long long key) {
        return (int)((key ^ (key >> 16)) % HASH_SIZE);
    }

    void hashPut(long long key, int val) {
        int h = hash(key);
        while (hashMap[h].key != -1 && hashMap[h].key != key) {
            h = (h + 1) % HASH_SIZE;
        }
        hashMap[h].key = key;
        hashMap[h].val = val;
    }

    int hashGet(long long key) {
        int h = hash(key);
        while (hashMap[h].key != -1) {
            if (hashMap[h].key == key) {
                return hashMap[h].val;
            }
            h = (h + 1) % HASH_SIZE;
        }
        return -1;
    }

    int minArea = INT_MAX;

    for (int i = 0; i < xsCount; i++) {
        int *yList = ysByX[i];
        int yLen = ysCount[i];
        // For each pair of y's in this x
        for (int a = 0; a < yLen; a++) {
            for (int b = a + 1; b < yLen; b++) {
                int y1 = yList[a];
                int y2 = yList[b];
                long long key = encodePair(y1, y2);
                int prevX = hashGet(key);
                if (prevX != -1) {
                    int area = (xs[i] - prevX) * (y2 - y1);
                    if (area < minArea) minArea = area;
                }
                // Update last seen x for this y-pair
                hashPut(key, xs[i]);
            }
        }
    }

    // Free memory
    for (int i = 0; i < xsCount; i++) {
        free(ysByX[i]);
    }
    free(ysByX);
    free(ysCount);
    free(xs);
    free(pts);
    free(hashMap);

    return minArea == INT_MAX ? 0 : minArea;
}

